const uint64_t kMaxSequenceNumber = ((0x1ull << 56) - 1);
const uint8_t kTypeValue = 0x1;
const uint8_t kTypeDeletion = 0x0;

ParsedInternalKey result;
if (internal_key.size() < 8) {
    return false;
}

uint64_t seq_type = DecodeFixed64(internal_key.data() + internal_key.size() - 8);
uint64_t sequence = seq_type >> 8;
uint8_t type = seq_type & 0xff;

if (sequence > kMaxSequenceNumber) {
    return false;
}

result.user_key = Slice(internal_key.data(), internal_key.size() - 8);
result.sequence = sequence;
result.type = static_cast<ValueType>(type);

*user_key = result.user_key;
*sequence = result.sequence;
*type = result.type;

return true;

